import{_ as o,a0 as n,w as r,s,ao as d,I as l,x as p,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"30个实例详解TOP命令 | LCTT x X-CMD","titleTemplate":false,"description":"30个实例详解TOP命令 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"30个实例详解TOP命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"30个实例详解TOP命令 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots","title":"30个实例详解TOP命令","tag":"201312","desc":""},"relativePath":"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots.md","filePath":"[post].md"}'),h={name:"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots.md"};function c(m,a,_,g,x,b){const e=n("Link");return r(),s("div",null,[a[11]||(a[11]=d(`<h1 id="_30个实例详解top命令" tabindex="-1">30个实例详解TOP命令 <a class="header-anchor" href="#_30个实例详解top命令" aria-label="Permalink to “30个实例详解TOP命令”">​</a></h1><p>Linux中的top命令显示系统上正在运行的进程。它是系统管理员最重要的工具之一。被广泛用于监视服务器的负载。在本篇中，我们会探索top命令的细节。top命令是一个交互命令。在运行top的时候还可以运行很多命令。我们也会探索这些命令。</p><p>（译注：不同发行版的top命令在各种细节有不同，如果发现不同时，请读你的帮助手册和命令内的帮助。）</p><h2 id="_1-top-命令输出" tabindex="-1">1. Top 命令输出: <a class="header-anchor" href="#_1-top-命令输出" aria-label="Permalink to “1. Top 命令输出:”">​</a></h2><p>首先，让我们了解一下输出。top命令会显示系统的很多信息。我们需要理解不同部分输出的意义：默认运行时，top命令会显示如下输出：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/01.top_default.png" alt="默认显示"></p><p>前几行水平显示了不同系统参数的概括，接下来是进程和它们在列中的属性。</p><h3 id="_1-1-系统运行时间和平均负载" tabindex="-1">1.1 系统运行时间和平均负载： <a class="header-anchor" href="#_1-1-系统运行时间和平均负载" aria-label="Permalink to “1.1 系统运行时间和平均负载：”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/02.top_uptime.png" alt="显示运行时间"></p><p>top命令的顶部显示与uptime命令相似的输出。</p><p>这些字段显示：</p><ul><li>当前时间</li><li>系统已运行的时间</li><li>当前登录用户的数量</li><li>相应最近5、10和15分钟内的平均负载。</li></ul><p>可以使用&#39;l&#39;命令切换uptime的显示。</p><h3 id="_1-2-任务" tabindex="-1">1.2 任务: <a class="header-anchor" href="#_1-2-任务" aria-label="Permalink to “1.2 任务:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/03.top_tasks.png" alt="任务概况"></p><p>第二行显示的是任务或者进程的总结。进程可以处于不同的状态。这里显示了全部进程的数量。除此之外，还有正在运行、睡眠、停止、僵尸进程的数量（僵尸是一种进程的状态）。这些进程概括信息可以用&#39;t&#39;切换显示。</p><h3 id="_1-3-cpu-状态" tabindex="-1">1.3 CPU 状态: <a class="header-anchor" href="#_1-3-cpu-状态" aria-label="Permalink to “1.3 CPU 状态:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/04.top_cpu_states.png" alt="CPU状态显示"></p><p>下一行显示的是CPU状态。 这里显示了不同模式下的所占CPU时间的百分比。这些不同的CPU时间表示:</p><ul><li>us, user： 运行(未调整优先级的) 用户进程的CPU时间</li><li>sy，system: 运行内核进程的CPU时间</li><li>ni，niced：运行已调整优先级的用户进程的CPU时间</li><li>wa，IO wait: 用于等待IO完成的CPU时间</li><li>hi：处理硬件中断的CPU时间</li><li>si: 处理软件中断的CPU时间</li><li>st：这个虚拟机被hypervisor偷去的CPU时间（译注：如果当前处于一个hypervisor下的vm，实际上hypervisor也是要消耗一部分CPU处理时间的）。</li></ul><p>可以使用&#39;t&#39;命令切换显示。</p><h3 id="_1-4-内存使用" tabindex="-1">1.4 内存使用: <a class="header-anchor" href="#_1-4-内存使用" aria-label="Permalink to “1.4 内存使用:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/05.top_mem_usage.png" alt="内存使用情况"></p><p>接下来两行显示内存使用率，有点像&#39;free&#39;命令。第一行是物理内存使用，第二行是虚拟内存使用(交换空间)。</p><p>物理内存显示如下:全部可用内存、已使用内存、空闲内存、缓冲内存。相似地：交换部分显示的是：全部、已使用、空闲和缓冲交换空间。</p><p>内存显示可以用&#39;m&#39;命令切换。</p><h3 id="_1-5-字段-列" tabindex="-1">1.5 字段/列: <a class="header-anchor" href="#_1-5-字段-列" aria-label="Permalink to “1.5 字段/列:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/06.top_fields.png" alt="任务信息列"></p><p>在横向列出的系统属性和状态下面，是以列显示的进程。不同的列代表下面要解释的不同属性。</p><p>默认上，top显示这些关于进程的属性：</p><p><strong>PID</strong></p><p>进程ID，进程的唯一标识符</p><p><strong>USER</strong></p><p>进程所有者的实际用户名。</p><p><strong>PR</strong></p><p>进程的调度优先级。这个字段的一些值是&#39;rt&#39;。这意味这这些进程运行在实时态。</p><p><strong>NI</strong></p><p>进程的nice值（优先级）。越小的值意味着越高的优先级。</p><p><strong>VIRT</strong></p><p>进程使用的虚拟内存。</p><p><strong>RES</strong></p><p>驻留内存大小。驻留内存是任务使用的非交换物理内存大小。</p><p><strong>SHR</strong></p><p>SHR是进程使用的共享内存。</p><p><strong>S</strong></p><p>这个是进程的状态。它有以下不同的值:</p><ul><li>D - 不可中断的睡眠态。</li><li>R – 运行态</li><li>S – 睡眠态</li><li>T – 被跟踪或已停止</li><li>Z – 僵尸态</li></ul><p><strong>%CPU</strong></p><p>自从上一次更新时到现在任务所使用的CPU时间百分比。</p><p><strong>%MEM</strong></p><p>进程使用的可用物理内存百分比。</p><p><strong>TIME+</strong></p><p>任务启动后到现在所使用的全部CPU时间，精确到百分之一秒。</p><p><strong>COMMAND</strong></p><p>运行进程所使用的命令。</p><p>还有许多在默认情况下不会显示的输出，它们可以显示进程的页错误、有效组和组ID和其他更多的信息。</p><h2 id="_2-交互命令" tabindex="-1">2. 交互命令: <a class="header-anchor" href="#_2-交互命令" aria-label="Permalink to “2. 交互命令:”">​</a></h2><p>我们之前说过top是一个交互命令。上一节我们已经遇到了一些命令。这里我们会探索更多的命令。</p><h3 id="_2-1-h-帮助" tabindex="-1">2.1 ‘h’: 帮助 <a class="header-anchor" href="#_2-1-h-帮助" aria-label="Permalink to “2.1 ‘h’: 帮助”">​</a></h3><p>首先，我们可以用&#39;h&#39;或者&#39;?&#39;显示交互命令的帮助菜单。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/07.top_help.png" alt="帮助菜单"></p><h3 id="_2-2-enter-或者-space-刷新显示" tabindex="-1">2.2 ‘&lt;ENTER&gt;’ 或者 ‘&lt;SPACE&gt;’: 刷新显示 <a class="header-anchor" href="#_2-2-enter-或者-space-刷新显示" aria-label="Permalink to “2.2 ‘&lt;ENTER&gt;’ 或者 ‘&lt;SPACE&gt;’: 刷新显示”">​</a></h3><p>top命令默认在一个特定间隔(3秒)后刷新显示。要手动刷新，用户可以输入回车或者空格。</p><h3 id="_2-3-a-切换交替显示模式" tabindex="-1">2.3 ‘A’: 切换交替显示模式 <a class="header-anchor" href="#_2-3-a-切换交替显示模式" aria-label="Permalink to “2.3 ‘A’: 切换交替显示模式”">​</a></h3><p>这个命令在全屏和交替模式间切换。在交替模式下会显示4个窗口（译注：分别关注不同的字段）:</p><ol><li>Def （默认字段组）</li><li>Job （任务字段组）</li><li>Mem （内存字段组）</li><li>Usr （用户字段组）</li></ol><p>这四组字段共有一个独立的可配置的概括区域和它自己的可配置任务区域。4个窗口中只有一个窗口是当前窗口。当前窗口的名称显示在左上方。（译注：只有当前窗口才会接受你键盘交互命令）</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/08.top_alternative_display.png" alt="交替显示"></p><p>我们可以用&#39;a&#39;和&#39;w&#39;在4个 窗口间切换。&#39;a&#39;移到后一个窗口，&#39;w&#39;移到前一个窗口。用&#39;g&#39;命令你可以输入一个数字来选择当前窗口。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/09.top_alternate_window_selection.png" alt="在交替显示中选择窗口"></p><h3 id="_2-4-b-触发粗体显示" tabindex="-1">2.4 ‘B’: 触发粗体显示 <a class="header-anchor" href="#_2-4-b-触发粗体显示" aria-label="Permalink to “2.4 ‘B’: 触发粗体显示”">​</a></h3><p>一些重要信息会以加粗字体显示。这个命令可以切换粗体显示。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/10.top_bold_display_off.png" alt="关闭粗体"></p><h3 id="_2-5-d-或-s-设置显示的刷新间隔" tabindex="-1">2.5 ‘d’ 或‘s’: 设置显示的刷新间隔 <a class="header-anchor" href="#_2-5-d-或-s-设置显示的刷新间隔" aria-label="Permalink to “2.5 ‘d’ 或‘s’: 设置显示的刷新间隔”">​</a></h3><p>当按下&#39;d&#39;或&#39;s&#39;时，你将被提示输入一个值（以秒为单位），它会以设置的值作为刷新间隔。如果你这里输入了1，top将会每秒刷新。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/11.top_display_time_interval.png" alt="刷新间隔l"></p><h3 id="_2-6-l-、-t-、-m-切换负载、任务、内存信息的显示" tabindex="-1">2.6 ‘l’、‘t’、‘m’: 切换负载、任务、内存信息的显示 <a class="header-anchor" href="#_2-6-l-、-t-、-m-切换负载、任务、内存信息的显示" aria-label="Permalink to “2.6 ‘l’、‘t’、‘m’: 切换负载、任务、内存信息的显示”">​</a></h3><p>这会相应地切换顶部的平均负载、任务/CPU状态和内存信息的概况显示。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/12.top_load_average_display_off.png" alt="不显示平均负载"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/13.top_cpu_display_off.png" alt="不显示CPU概况"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/14.top_mem_display_off.png" alt="不显示内存和交换内存概况"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/15.top_all_three_display_off.png" alt="上面三个全不显示"></p><h3 id="_2-7-f-字段管理" tabindex="-1">2.7 ‘f’: 字段管理 <a class="header-anchor" href="#_2-7-f-字段管理" aria-label="Permalink to “2.7 ‘f’: 字段管理”">​</a></h3><p>用于选择你想要显示的字段。用&#39;*&#39;标记的是已选择的。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/16.top_field_management.png" alt="管理显示列"></p><p>上下光标键在字段内导航，左光标键可以选择字段，回车或右光标键确认。</p><p>按&#39;&lt;&#39;移动已排序的字段到左边，&#39;&gt;&#39;则移动到右边。</p><h3 id="_2-8-r-反向排序" tabindex="-1">2.8 ‘R’: 反向排序 <a class="header-anchor" href="#_2-8-r-反向排序" aria-label="Permalink to “2.8 ‘R’: 反向排序”">​</a></h3><p>切换反向/常规排序。</p><h3 id="_2-9-c-触发命令" tabindex="-1">2.9 ‘c’: 触发命令 <a class="header-anchor" href="#_2-9-c-触发命令" aria-label="Permalink to “2.9 ‘c’: 触发命令”">​</a></h3><p>切换是否显示进程启动时的完整路径和程序名。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/17.top_command_name_displayed.png" alt="完整命令路径"></p><h3 id="_2-10-i-空闲任务" tabindex="-1">2.10 ‘i’: 空闲任务 <a class="header-anchor" href="#_2-10-i-空闲任务" aria-label="Permalink to “2.10 ‘i’: 空闲任务”">​</a></h3><p>切换显示空闲任务。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/18.top_idle_tasks_off.png" alt="不显示空闲命令"></p><h3 id="_2-11-v-树视图" tabindex="-1">2.11 ‘V’: 树视图 <a class="header-anchor" href="#_2-11-v-树视图" aria-label="Permalink to “2.11 ‘V’: 树视图”">​</a></h3><p>切换树视图。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/19.top_forest_view.png" alt="树视图"></p><h3 id="_2-12-z-改变配色" tabindex="-1">2.12 ‘Z’: 改变配色 <a class="header-anchor" href="#_2-12-z-改变配色" aria-label="Permalink to “2.12 ‘Z’: 改变配色”">​</a></h3><p>按下&#39;Z&#39;向用户显示一个改变top命令的输出颜色的屏幕。可以为8个任务区域选择8种颜色。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/20.top_color_selection.png" alt="定制颜色"></p><p>下面显示的是4中颜色显示的top视图。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/21.top_colored.png" alt="彩色显示"></p><h3 id="_2-13-z-切换彩色显示" tabindex="-1">2.13 ‘z’: 切换彩色显示 <a class="header-anchor" href="#_2-13-z-切换彩色显示" aria-label="Permalink to “2.13 ‘z’: 切换彩色显示”">​</a></h3><p>切换彩色，即打开或关闭彩色显示。</p><h3 id="_2-14-x-或者-y" tabindex="-1">2.14 ‘x’ 或者 ‘y’ <a class="header-anchor" href="#_2-14-x-或者-y" aria-label="Permalink to “2.14 ‘x’ 或者 ‘y’”">​</a></h3><p>切换高亮信息：&#39;x&#39;将排序字段高亮显示（纵列）；&#39;y&#39;将运行进程高亮显示（横行）。依赖于你的显示设置，你可能需要让输出彩色来看到这些高亮。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/22.top_x_y_displayed.png" alt="X 和 Y高亮"></p><h3 id="_2-15-u-特定用户的进程" tabindex="-1">2.15 ‘u’: 特定用户的进程 <a class="header-anchor" href="#_2-15-u-特定用户的进程" aria-label="Permalink to “2.15 ‘u’: 特定用户的进程”">​</a></h3><p>显示特定用户的进程。你会被提示输入用户名。空白将会显示全部用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/23.top_raghu_processes.png" alt="raghu的进程"></p><h3 id="_2-16-n-或-任务的数量" tabindex="-1">2.16 ‘n’ 或 ‘#’: 任务的数量 <a class="header-anchor" href="#_2-16-n-或-任务的数量" aria-label="Permalink to “2.16 ‘n’ 或 ‘#’: 任务的数量”">​</a></h3><p>设置最大显示的任务数量</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/24.top_10_processes.png" alt="设置最大显示的任务数量"></p><h3 id="_2-17-k-结束任务" tabindex="-1">2.17 ‘k’: 结束任务 <a class="header-anchor" href="#_2-17-k-结束任务" aria-label="Permalink to “2.17 ‘k’: 结束任务”">​</a></h3><p>top命令中最重要的一个命令之一。用于发送信号给任务（通常是结束任务）。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/25.top_kill_task.png" alt="杀死一个任务"></p><h3 id="_2-18-r-重新设置优先级" tabindex="-1">2.18 ‘r’: 重新设置优先级 <a class="header-anchor" href="#_2-18-r-重新设置优先级" aria-label="Permalink to “2.18 ‘r’: 重新设置优先级”">​</a></h3><p>重新设置一个任务的调度优先级。</p><h2 id="_3-命令行选项" tabindex="-1">3. 命令行选项: <a class="header-anchor" href="#_3-命令行选项" aria-label="Permalink to “3. 命令行选项:”">​</a></h2><p>这些命令行选项与上面讨论的命令大多相同。top的输出可以用命令交互操作，但是你也可以带参数运行top来设置你想要的效果。</p><h3 id="_3-1-b-批处理模式" tabindex="-1">3.1 -b: 批处理模式 <a class="header-anchor" href="#_3-1-b-批处理模式" aria-label="Permalink to “3.1 -b: 批处理模式”">​</a></h3><p>-b选项以批处理模式启动top命令。当你想要在文件中保存输出时是很有用的。</p><h3 id="_3-2-c-命令-程序名-触发" tabindex="-1">3.2 -c: 命令/程序名 触发: <a class="header-anchor" href="#_3-2-c-命令-程序名-触发" aria-label="Permalink to “3.2 -c: 命令/程序名 触发:”">​</a></h3><p>如上面所讨论到的命令，这个选项会以上次记住的程序/命令显示的状态显示（是否显示完整路径）。</p><h3 id="_3-3-d-设置延迟间隔" tabindex="-1">3.3 -d: 设置延迟间隔 <a class="header-anchor" href="#_3-3-d-设置延迟间隔" aria-label="Permalink to “3.3 -d: 设置延迟间隔”">​</a></h3><p>设置top的显示间隔(以秒计)。比如。</p><pre><code>$ top -d 1 
</code></pre><p>将会以1秒的刷新间隔启动top。</p><h3 id="_3-4-i-切换显示空闲进程" tabindex="-1">3.4 -i: 切换显示空闲进程 <a class="header-anchor" href="#_3-4-i-切换显示空闲进程" aria-label="Permalink to “3.4 -i: 切换显示空闲进程”">​</a></h3><p>这个选项设置top命令的上一次记住的<strong>相反的</strong>&#39;i&#39;状态。</p><h3 id="_3-5-n-设置迭代数量" tabindex="-1">3.5 -n: 设置迭代数量 <a class="header-anchor" href="#_3-5-n-设置迭代数量" aria-label="Permalink to “3.5 -n: 设置迭代数量”">​</a></h3><p>用-n选项，你可以设置top退出前迭代的次数。</p><pre><code>$ top -n 3 
</code></pre><p>将会在刷新输出3次后退出。</p><h3 id="_3-6-p-监控特定的pid" tabindex="-1">3.6 -p: 监控特定的PID <a class="header-anchor" href="#_3-6-p-监控特定的pid" aria-label="Permalink to “3.6 -p: 监控特定的PID”">​</a></h3><p>你可以用-p选项监控指定的PID。PID的值为0将被作为top命令自身的PID。</p><h3 id="_3-7-u-或-u-用户名-或者-uid" tabindex="-1">3.7 -u 或 -U: 用户名 或者 UID <a class="header-anchor" href="#_3-7-u-或-u-用户名-或者-uid" aria-label="Permalink to “3.7 -u 或 -U: 用户名 或者 UID”">​</a></h3><p>可以用这些选项浏览特定用户的进程。用户名或者UID可以在选项中指定。-p、-u和-U选项是互斥的，同时只可以使用这其中一个选项。当你试图组合使用这些选项时，你会得到一个错误:</p><pre><code>$ top -p 28453 -u raghu
top: conflicting process selections (U/p/u) 
</code></pre><hr>`,141)),l("p",null,[a[1]||(a[1]=p("via: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-top-command-examples-screenshots/"},{default:i(()=>[...a[0]||(a[0]=[p("http://linoxide.com/linux-command/linux-top-command-examples-screenshots/",-1)])]),_:1})]),l("p",null,[a[4]||(a[4]=p("译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[2]||(a[2]=[p("geekpi",-1)])]),_:1}),a[5]||(a[5]=p(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[3]||(a[3]=[p("wxy",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=p("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[6]||(a[6]=[p("LCTT",-1)])]),_:1}),a[9]||(a[9]=p(" 原创翻译，",-1)),t(e,{href:"http://linux.cn/"},{default:i(()=>[...a[7]||(a[7]=[p("Linux中国",-1)])]),_:1}),a[10]||(a[10]=p(" 荣誉推出",-1))])])}const k=o(h,[["render",c]]);export{f as __pageData,k as default};
